interfaces.interface:
export interface CompositorClip {
  id: string;
  trackId: string;
  trackIndex: number;
  sourceFile: string;
  startTime: number;
  duration: number;
  trimIn: number;
  trimOut: number;
  opacity: number;
  // NEW FIELDS FOR PIP:
  pipPosition?: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';
  pipSize?: number;  // Percentage, clamped to [0.05, 0.5]
  showBorder?: boolean; // Default true for trackIndex > 0
}

export class AudioMixer {
  private audioContext: AudioContext | null;
  private sourceNodes: Map<HTMLVideoElement, MediaElementAudioSourceNode>;
  private gainNodes: Map<HTMLVideoElement, GainNode>;

  initializeContext(): void;
  connectVideo(video: HTMLVideoElement, trackIndex: number): void;
  disconnectVideo(video: HTMLVideoElement): void;
  setGain(video: HTMLVideoElement, gain: number): void;
  resumeContext(): Promise<void>;
  dispose(): void;
}

// Usage in VideoCompositor:
// - Create instance in constructor
// - Call connectVideo() in loadVideoSource()
// - Call disconnectVideo() in unloadVideoSource()
// - Call dispose() in dispose()
